let user = { name: 'Alice' }; // Rents space in the Heap

const admin = user; // 'admin' points to the same Heap address

user = null; 
// Is the object garbage collected? 
// NO! 'admin' still has the key to the storage unit.

admin = null;
// Now NO variable points to the object. It is unreachable.
// The Mark-and-Sweep algorithm will delete it on its next pass.
